#include <iostream>
#include <memory>
struct A; struct B;
struct A { std::shared_ptr<B> b; ~A(){ std::cout << "~A\n"; } };
struct B { std::weak_ptr<A>   a; ~B(){ std::cout << "~B\n"; } };   // 弱引用：不增强计数
int main() {
    auto a = std::make_shared<A>();
    auto b = std::make_shared<B>();
    a->b = b; b->a = a;                  // 仅 A 强持有 B，B 弱观察 A → 环被打破
    std::cout << "count a=" << a.use_count() << " b=" << b.use_count() << '\n';
}                                        // 作用域结束：~A ~B 都会打印
